css:
body {
    margin: 0;
    padding: 0;
    background: #ffffff;
}

.certificate-wrapper {
    width: 100%;
    min-height: 700px;
    box-sizing: border-box;
    padding: 28px;
    background: #f6f9fc;
    font-family: 'Inter', 'Arial', sans-serif;
    color: #172033;
}

.certificate-shell {
    min-height: 644px;
    border: 12px solid #0a2351;
    background: #ffffff;
    position: relative;
    box-sizing: border-box;
    overflow: hidden;
}

.certificate-shell:before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 18px;
    background: #d8a538;
}

.certificate-shell:after {
    content: '';
    position: absolute;
    right: -90px;
    bottom: -90px;
    width: 260px;
    height: 260px;
    border: 34px solid rgba(10, 35, 81, 0.08);
    border-radius: 50%;
}

.certificate-content {
    position: relative;
    z-index: 1;
    min-height: 600px;
    padding: 42px 58px 36px 58px;
    box-sizing: border-box;
    text-align: center;
}

.cert-header {
    margin-bottom: 22px;
}

.cert-logo {
    max-height: 54px;
    display: block;
    margin: 0 auto 18px auto;
}

.cert-kicker {
    color: #0a2351;
    font-size: 13px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0;
}

.cert-title {
    margin: 8px 0 8px 0;
    color: #0a2351;
    font-size: 40px;
    line-height: 1.1;
    font-weight: 900;
    letter-spacing: 0;
}

.cert-subtitle {
    color: #64748b;
    font-size: 15px;
    line-height: 1.5;
}

.cert-name {
    display: inline-block;
    min-width: 58%;
    margin: 22px auto 18px auto;
    padding: 0 28px 12px 28px;
    border-bottom: 3px solid #d8a538;
    color: #0a2351;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 46px;
    font-style: italic;
    line-height: 1.15;
    font-weight: 700;
}

.cert-body {
    width: 78%;
    margin: 0 auto 26px auto;
    color: #334155;
    font-size: 18px;
    line-height: 1.65;
}

.cert-course {
    display: block;
    margin: 8px 0;
    color: #0a2351;
    font-size: 25px;
    line-height: 1.25;
    font-weight: 800;
}

.cert-meta {
    display: inline-block;
    margin: 6px auto 26px auto;
    padding: 10px 18px;
    border-radius: 8px;
    background: #eef4fb;
    color: #0a2351;
    font-size: 14px;
    font-weight: 700;
}

.cert-footer {
    margin-top: 18px;
    width: 100%;
}

.signature-line {
    border-top: 1px solid #9fb1c8;
    width: 76%;
    margin: 0 auto 10px auto;
}

.signature-title {
    color: #334155;
    font-size: 14px;
    line-height: 1.4;
    font-weight: 700;
}

.signature-role {
    color: #64748b;
    font-size: 12px;
    font-weight: 500;
}

.cert-badge {
    width: 94px;
    height: 94px;
    margin: 0 auto;
    border-radius: 50%;
    background: #0a2351;
    border: 5px solid #d8a538;
    color: #ffffff;
    text-align: center;
    box-sizing: border-box;
}

.cert-badge-main {
    display: block;
    margin-top: 23px;
    font-size: 13px;
    line-height: 1.1;
    font-weight: 900;
}

.cert-badge-sub {
    display: block;
    margin-top: 4px;
    color: #f8e6b1;
    font-size: 10px;
    line-height: 1.2;
    font-weight: 800;
}

.cert-id {
    margin-top: 20px;
    color: #94a3b8;
    font-size: 11px;
}
